    panel.appendChild(row);
    root.appendChild(panel);
    var sourcePanel = element("div", "reroll-source-panel");
    sourcePanel.appendChild(element("p", "reroll-section-title", "Suggestions come from"));
    sourcePanel.appendChild(element("p", "reroll-section-hint", "New tasks are ideas the plugin proposes for your projects."));
    var sourceRow = element("div", "reroll-source-row");
    sourceOptions.forEach(function (option) {
      var sourceLabel = element("label", "reroll-source-option");
      var input = element("input");
      input.type = "radio";
      input.name = "reroll-source";
      input.value = option.key;
      input.checked = option.key === value.sourceKey;
      input.addEventListener("change", function () { value.sourceKey = option.key; send(); });
      sourceLabel.appendChild(input);
      sourceLabel.appendChild(element("span", null, option.label));
      sourceRow.appendChild(sourceLabel);
    });
    sourcePanel.appendChild(sourceRow);
    root.appendChild(sourcePanel);
    function timeOption(key, labelText, hintText) {
      var option = element("label", "reroll-time-option");
      var input = element("input");
      input.type = "checkbox";
      input.checked = Boolean(value[key]);
      input.addEventListener("change", function () { value[key] = input.checked; send(); });
      option.appendChild(input);
      option.appendChild(element("span", null, labelText));
      option.appendChild(element("span", "reroll-time-hint", hintText));
      return option;
    }
    var timePanel = element("div", "reroll-time-panel");
    timePanel.appendChild(element("p", "reroll-section-title", "Also suggest for"));
    if (value.offersWeekends) timePanel.appendChild(timeOption("includeWeekends", "Weekends", "The Saturday and Sunday on your calendar"));
    timePanel.appendChild(timeOption("includeEvenings", "Evenings", "Hours from 6pm until 10pm"));
    root.appendChild(timePanel);
    var summary = element("p", "reroll-summary-text");
    root.appendChild(summary);
    refresh();
